// Re-records the cases of node-domain.controls.json from real Node:
//   docker run --rm -v "$PWD":/w node:24.18.1-alpine node /w/record.cjs /w/node-domain.controls.json > new.json
// (save this text as record.cjs next to a copy of the controls file). Each case runs in its own process; its body is
// the text of a function (require, process, out, setTimeout, setInterval, clearInterval, setImmediate, queueMicrotask).
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const controls = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const parameters = ["require", "process", "out", "setTimeout", "setInterval", "clearInterval", "setImmediate", "queueMicrotask"];
if (process.argv[3] !== undefined) {
  const events = [];
  // Node emits no 'exit' when the exception handler itself fails (exit code 7): such a case records no events.
  process.on("exit", () => { fs.writeSync(1, "\n@@" + JSON.stringify(events) + "\n"); });
  const body = controls.cases.find((entry) => entry.name === process.argv[3]).body;
  new Function(...parameters, controls.prelude + body)(require, process, (value) => { events.push(value); }, setTimeout, setInterval, clearInterval, setImmediate, queueMicrotask);
} else {
  const cases = controls.cases.map(({ name, body }) => {
    const child = spawnSync(process.execPath, [__filename, process.argv[2], name], { encoding: "utf8" });
    const marker = child.stdout.lastIndexOf("\n@@");
    const first = child.stderr.split("\n").find((line) => /^[A-Za-z]*Error( \[\w+\])?: /.test(line)) ?? null;
    return { name, body, code: child.status, events: marker === -1 ? null : JSON.parse(child.stdout.slice(marker + 3)), stderr: first };
  });
  console.log(JSON.stringify({ node: process.version, recorder: fs.readFileSync(__filename, "utf8"), prelude: controls.prelude, cases }, null, 1));
}

